def _agents(db: Path) -> dict[str, str]:
    try:
        con = sqlite3.connect(f"file:{db}?mode=ro", uri=True)
        rows = {sid: (agent or "") for sid, agent in con.execute("SELECT id, agent FROM session")}
        con.close()
        return rows
    except sqlite3.Error:
        return {}


def _tools(db: Path) -> dict[str, list[str]]:
    con = sqlite3.connect(f"file:{db}?mode=ro", uri=True)
    by: dict[str, list[str]] = {}
    for sid, _ts, raw in con.execute(
        "SELECT session_id, time_created, data FROM part ORDER BY session_id, time_created"
    ):
        obj = json.loads(raw)
        t = obj.get("type")
        name = None
        if t == "patch":
            name = "patch"
        elif t == "tool":
            tool = obj.get("tool")
            if isinstance(tool, str):
                name = tool
        if name:
            by.setdefault(sid, []).append(name)
    con.close()
    return by


